(1779,17,'en-da','Cricket 22 The Official Game Of The Ashes','Cricket 22 det officielle spil for Ashes','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1780,17,'en-da','Product Sub-Header - Maximum 80 Characters','Product Sub-Header - Maximum 80 Characters','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1781,17,'en-da','The next generation of cricket is here - better, bigger, bolder than ever! ','Næste generation cricket er her - bedre, større, dristigere end nogensinde før! ','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1782,17,'en-da','Marketing Copy - Maximum 3900 Characters','Marketing Copy - Maximum 3900 Characters','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1783,17,'en-da','Cricket 22 delivers the most robust, substantial game of cricket that fans have ever seen. Enjoy the full licensed Ashes contest – the pinnacle of the long-standing rivalry between Australia and England. In addition, contest Australia’s big-hitting Big Bash T20 competition, the hugely innovative The Hundred in England, the tropical party of the CPL in the Caribbean, and take to the international field of battle with fully-licensed teams from Australia, England, The West Indies, New Zealand and Ireland. ','Cricket 22 giver den mest robuste, betydelige omgang cricket, som fans nogensinde har prøvet. Nyd indhold med fuld licens fra Ashes - højdepunktet af den gamle fejde mellem Australien og England. Derudover kæmpes i Australiens store konkurrence Big Bash T20, den yderst opfindsomme The Hundred i England, den tropiske fest i CPL i Caribbien og den internationale slagmark med fuldt licenserede hold fra Australien, England, De Vestindiske Øer, New Zealand og Irland. ','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1784,17,'en-da','And, in keeping with Big Ant’s commitment to equality and equal representation, both the Men’s and Women’s games have been replicated across all of Cricket 22.','Og traditionen tro med Big Ants forpligtelse på lighed og lige repræsentation er både herrer og damers kampe blevet genskabt på tværs af Cricket 22.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1785,17,'en-da','Cricket 22 also features a bevy of new innovations, including:','Cricket 22 har også en lang række nyskabelser såsom:','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1786,17,'en-da','All-new bowling and fielding controls; whether it’s a feisty fast bouncer, or the satisfying “snap” as you hurl the ball from the infield for a precision run-out, Cricket 22 features refined, tight controls that enable you to play your best game of cricket.','Helt ny styring for bowling og fielding; uanset om det er en lynhurtig hopper eller det tilfredsstillende \"snap\", når du kaster bolden fra marken for et præcisionsløb, så har Cricket 22 finjusteret, stram styring, som lader dig spille dit bedste spil cricket.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1787,17,'en-da','A deep, narrative-driven career mode; you are in control on and off the field. You manage your training and press conferences, deal with injuries, and decide your path towards international glory!','En dyb, historiedrevet karrieretilstand; du har styringen på og uden for banen. Du styrer din træning og pressekonferencer, håndterer skader og bestemmer din vej mod international hæder!','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1788,17,'en-da','It’s the most accessible cricket game yet; New to Cricket? Cricket 22 makes it easier to get into the game than ever before, with a completely overhauled series of tutorials and first-time user experience. Cricket 22 is the most detailed simulation of the sport that Big Ant has ever created, and thanks to these tutorials we’ll have you out there batting and bowling like a pro in no time.','Det er det mest tilgængelige cricket-spil hidtil; ny cricket-spiller? Cricket 22 gør det lettere end nogensinde før at blive bekendt med spillet med en helt nytænkt række vejledninger og førstegangs brugeroplevelser. Cricket 22 er den mest detaljerede simulation af sporten, som Big Ant nogensinde har lavet, og takket være disse vejledninger vil du batte og bowle som en prof i løbet af ingen tid.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1789,17,'en-da','An all-new commentary team; Cricket 22 brings a star-studded commentary team, featuring Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell and David Gower. Every shot will be called with greater depth and analysis than ever before, and for the first time ever in a sports game, there will be an all-women commentary team, further deepening the representation of women in the Cricket 22 experience.','Et helt nyt kommentatorhold; Cricket 22 har et stjernespækket kommentatorhold med Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell og David Gower. Hver handling kommenteres med mere dybde og analyse end nogensinde før, og for første gang i et sportshold vil der være et rent kvindeligt kommentatorhold, hvilket yderligere uddyber repræsentationen af kvinder i Cricket 22-oplevelsen.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1790,17,'en-da','The best-looking cricket ever; Cricket 22 takes full advantage of the capabilities of the latest generation of hardware. Not only does the game load with blinding speed, getting you into the action more quickly than ever before, it also includes a full suite of visual updates, including incredible real-time ray tracing elements, providing the most visually realistic game of cricket ever seen.','Det bedste udseende for cricket nogensinde; Cricket 22 udnytter fuldt ud kapaciteten for den nyeste generation af hardware. Udover at spillet indlæses med lynets hastighed, så du kommer ind i handlingen hurtigere end nogensinde før, så har det også en fuld række visuelle opdateringer, inklusiv utrolige linjesporingselementer i realtid, så du får det mest visuelt realistiske spil cricket nogensinde.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1791,17,'en-da','Short Description - Maximum 270 Characters','Short Description - Maximum 270 Characters','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1792,17,'en-da','Cricket 22 delivers the Ashes, the Big Bash, The Hundred, and a multitude of other fan-favourite competitions! All-new mechanics, commentary, and a captivating, narrative driven career mode, will immediately immerse you in the ultimate cricket experience to date.','Cricket 22 giver Ashes, Big Bash, Hundred og en lang række af andre foretrukne konkurrencer! Nye mekanismer, kommentarer og en fængslende, historiedrevet karrieretilstand vil øjeblikkeligt fordybe dig i den ultimative cricket-oplevelse.','DONE','2026-04-15 16:35:00','2026-04-15 16:35:00'),
(1793,18,'en-nl','Cricket 22 The Official Game Of The Ashes','Cricket 22 De Officiële Game Van The Ashes','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1794,18,'en-nl','Product Sub-Header - Maximum 80 Characters','Product Sub-Header - Maximum 80 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1795,18,'en-nl','The next generation of cricket is here - better, bigger, bolder than ever! ','De volgende generatie van cricket is hier - beter, groter en stoerder dan ooit! ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1796,18,'en-nl','Marketing Copy - Maximum 3900 Characters','Marketing Copy - Maximum 3900 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1797,18,'en-nl','Cricket 22 delivers the most robust, substantial game of cricket that fans have ever seen. Enjoy the full licensed Ashes contest – the pinnacle of the long-standing rivalry between Australia and England. In addition, contest Australia’s big-hitting Big Bash T20 competition, the hugely innovative The Hundred in England, the tropical party of the CPL in the Caribbean, and take to the international field of battle with fully-licensed teams from Australia, England, The West Indies, New Zealand and Ireland. ','Cricket 22 levert het meest robuuste en omvangrijke cricketspel dat fans ooit hebben gezien. Beleef plezier met de volledig geautoriseerde The Ashes-competitie - het hoogtepunt van de langdurige rivaliteit tussen Australië en Engeland. Of neem deel aan de big-hitting Big Bash T20-competitie in Australië, de innovatieve The Hundred in Engeland, het tropisch feestje van de CPL in de Caraïben of ga de internationale strijd aan met volledig geautoriseerde teams uit Australië, Engeland, West-Indië, Nieuw-Zeeland en Ierland. ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1798,18,'en-nl','And, in keeping with Big Ant’s commitment to equality and equal representation, both the Men’s and Women’s games have been replicated across all of Cricket 22.','En met inachtneming van Big Ant’s toewijding voor gelijkheid en gelijke vertegenwoordiging, kunnen er zowel wedstrijden voor mannen als vrouwen in Cricket 22 worden nagespeeld.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1799,18,'en-nl','Cricket 22 also features a bevy of new innovations, including:','Cricket 22 is tevens voorzien van vele innovaties, waaronder:','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1800,18,'en-nl','All-new bowling and fielding controls; whether it’s a feisty fast bouncer, or the satisfying “snap” as you hurl the ball from the infield for a precision run-out, Cricket 22 features refined, tight controls that enable you to play your best game of cricket.','Volledig nieuwe bowl- en fieldbesturing; of het nu een felle, snelle bouncer betreft of de bevredigende ‘knip’ terwijl je de bal vanuit het binnenveld gooit, Cricket 22 is voorzien van een verfijnde en strikte besturing om je het beste cricketspel ooit te laten spelen.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1801,18,'en-nl','A deep, narrative-driven career mode; you are in control on and off the field. You manage your training and press conferences, deal with injuries, and decide your path towards international glory!','Een uitgebreide en verhalende carrièremodus; jij bent in controle, zowel op als van het veld. Jij regelt de trainingen en persconferenties, behandelt de kwetsuren en beslist je pad naar internationale roem!','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1802,18,'en-nl','It’s the most accessible cricket game yet; New to Cricket? Cricket 22 makes it easier to get into the game than ever before, with a completely overhauled series of tutorials and first-time user experience. Cricket 22 is the most detailed simulation of the sport that Big Ant has ever created, and thanks to these tutorials we’ll have you out there batting and bowling like a pro in no time.','Het is het meest toegankelijke cricketspel tot op heden; Nieuw in Cricket? Cricket 22 zorgt ervoor dat je het spel snel onder de knie krijgt, dit is nog nooit zo eenvoudig geweest, met een volledige reeks handleidingen en gebruikerservaringen van beginnelingen. Cricket 22 is de meest gedetailleerde sportsimulatie die Big Ant ooit heeft gemaakt, en dankzij deze handleidingen zul je snel batten en bowlen als een echte prof.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1803,18,'en-nl','An all-new commentary team; Cricket 22 brings a star-studded commentary team, featuring Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell and David Gower. Every shot will be called with greater depth and analysis than ever before, and for the first time ever in a sports game, there will be an all-women commentary team, further deepening the representation of women in the Cricket 22 experience.','Een gloednieuw commentaarteam; Cricket 22 brengt een met sterren bezaaid commentaarteam, bestaande uit Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell en David Gower. Elke slag wordt voorzien van een diepgaande bespreking en analyse zoals nooit tevoren, en voor de eerste keert ooit in een sportgame is er een commentaarteam uit enkel vrouwen, voor een grotere vertegenwoordiging van vrouwen in de Cricket 22 ervaring.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1804,18,'en-nl','The best-looking cricket ever; Cricket 22 takes full advantage of the capabilities of the latest generation of hardware. Not only does the game load with blinding speed, getting you into the action more quickly than ever before, it also includes a full suite of visual updates, including incredible real-time ray tracing elements, providing the most visually realistic game of cricket ever seen.','De best uitziende cricket ooit; Cricket 22 profiteert optimaal van de mogelijkheden van de allernieuwste generatie van hardware. Het spel wordt niet alleen snel geladen, je krijgt de actie tevens sneller dan ooit tevoren. Het bevat tevens een volledige reeks van visuele updates, waaronder geweldige real-time ray tracing-elementen voor het meest visueel realistisch cricketspel ooit gezien.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1805,18,'en-nl','Short Description - Maximum 270 Characters','Short Description - Maximum 270 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1806,18,'en-nl','Cricket 22 delivers the Ashes, the Big Bash, The Hundred, and a multitude of other fan-favourite competitions! All-new mechanics, commentary, and a captivating, narrative driven career mode, will immediately immerse you in the ultimate cricket experience to date.','Cricket 22 biedt The Ashes, The Big Bash, The Hundred en vele andere populaire competities! De volledig nieuwe mechanica en commentaar en een beklijvende, verhalende carrièremodus zullen je onmiddellijk onderdompelen in de ultieme cricketervaring tot op heden. ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1807,19,'en-fi','Cricket 22 The Official Game Of The Ashes','Cricket 22 – Virallinen The Ashes -peli','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1808,20,'en-fi','Product Sub-Header - Maximum 80 Characters','Product Sub-Header - Maximum 80 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1809,21,'en-fi','The next generation of cricket is here - better, bigger, bolder than ever! ','Kriketin seuraava sukupolvi on täällä – isompana ja parempana kuin koskaan! ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1810,22,'en-fi','Marketing Copy - Maximum 3900 Characters','Marketing Copy - Maximum 3900 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1811,23,'en-fi','Cricket 22 delivers the most robust, substantial game of cricket that fans have ever seen. Enjoy the full licensed Ashes contest – the pinnacle of the long-standing rivalry between Australia and England. In addition, contest Australia’s big-hitting Big Bash T20 competition, the hugely innovative The Hundred in England, the tropical party of the CPL in the Caribbean, and take to the international field of battle with fully-licensed teams from Australia, England, The West Indies, New Zealand and Ireland. ','Cricket 22 tarjoaa kaikkien aikojen kattavimman ja vakaimman krikettipelikokemuksen. Nauti täydestä lisensoidusta Ashes-sisällöstä ja koe Australian ja Englannin pitkäaikaisen kilpailun huipentuma. Osallistu myös Australian maineikkaaseen Big Bash T20 -kilpailuun, innovatiiviseen The Hundred -kilpailuun Englannissa sekä trooppiseen CPL-juhlaan Karibialla, ja lähde taistelemaan kansainvälisillä pelikentillä lisensoiduilla joukkueilla Australiasta, Englannista, Länsi-Intian saaristosta, Uudesta-Seelannista ja Irlannista. ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1812,24,'en-fi','And, in keeping with Big Ant’s commitment to equality and equal representation, both the Men’s and Women’s games have been replicated across all of Cricket 22.','Big Antin sitoutumisesta tasavertaisuuteen ja tasa-arvoiseen representaatioon kertoo sekä miesten että naisten sarjojen mukanaolo Cricket 22 -pelissä.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1813,25,'en-fi','Cricket 22 also features a bevy of new innovations, including:','Cricket 22 sisältää myös runsaasti uusia innovaatioita:','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1814,26,'en-fi','All-new bowling and fielding controls; whether it’s a feisty fast bouncer, or the satisfying “snap” as you hurl the ball from the infield for a precision run-out, Cricket 22 features refined, tight controls that enable you to play your best game of cricket.','Upouusi syöttö ja peliohjaus: Cricket 22 -pelin uudistetun ohjauksen avulla voit pelata parasta peliäsi niin nopeana syöttäjänä, vahvana lyöjänä kuin nopeana juoksijana.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1815,27,'en-fi','A deep, narrative-driven career mode; you are in control on and off the field. You manage your training and press conferences, deal with injuries, and decide your path towards international glory!','Monipuolinen, tarinapohjainen uratila: Ohjat ovat sinulla sekä kentällä että sen ulkopuolella – hallitse harjoittelua ja lehdistötilaisuuksia, hoida vammat ja raivaa oma polkusi kohti kansainvälistä kunniaa!','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1816,28,'en-fi','It’s the most accessible cricket game yet; New to Cricket? Cricket 22 makes it easier to get into the game than ever before, with a completely overhauled series of tutorials and first-time user experience. Cricket 22 is the most detailed simulation of the sport that Big Ant has ever created, and thanks to these tutorials we’ll have you out there batting and bowling like a pro in no time.','Kaikkien aikojen helpoimmin lähestyttävä krikettipeli: Onko kriketti sinulle uusi laji? Cricket 22 tekee lajin aloittamisesta helpompaa kuin koskaan aiemmin – peli sisältää uudistettuja tutoriaaleja ja vasta-alkajan ohjeita. Cricket 22 on Big Antin kaikkien aikojen yksityiskohtaisin simulaatio lajista, ja tutoriaalien avulla pääset peliin kiinni hyvin nopeasti.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1817,29,'en-fi','An all-new commentary team; Cricket 22 brings a star-studded commentary team, featuring Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell and David Gower. Every shot will be called with greater depth and analysis than ever before, and for the first time ever in a sports game, there will be an all-women commentary team, further deepening the representation of women in the Cricket 22 experience.','Täysin uusi selostustiimi: Cricket 22 sisältää tarunhohtoisen selostustiimin, johon kuuluvat Michael Atherton, Ian Healy, Mel Jones, Alison Mitchell ja David Gower. Jokainen lyönti selostetaan ja analysoidaan syvällisemmin kuin koskaan aiemmin, ja ensimmäistä kertaa urheilupelien historiassa pelissä on myös täysin naispuolinen selostustiimi, mikä syventää naisten representaatiota Cricket 22 -kokemuksessa entisestään.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1818,30,'en-fi','The best-looking cricket ever; Cricket 22 takes full advantage of the capabilities of the latest generation of hardware. Not only does the game load with blinding speed, getting you into the action more quickly than ever before, it also includes a full suite of visual updates, including incredible real-time ray tracing elements, providing the most visually realistic game of cricket ever seen.','Kaikkien aikojen parhaan näköinen krikettipeli: Cricket 22 ottaa kaiken hyödyn irti uuden sukupolven laitteiden tehoista – huippunopeiden latausaikojen ansiosta siirryt peliin nopeammin kuin koskaan ennen, ja reaaliaikaiset säteenseurantaominaisuudet ja muut visuaaliset uudistukset tekevät pelistä realistisimman krikettikokemuksen, jonka olet koskaan nähnyt.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1819,31,'en-fi','Short Description - Maximum 270 Characters','Short Description - Maximum 270 Characters','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1820,32,'en-fi','Cricket 22 delivers the Ashes, the Big Bash, The Hundred, and a multitude of other fan-favourite competitions! All-new mechanics, commentary, and a captivating, narrative driven career mode, will immediately immerse you in the ultimate cricket experience to date.','Cricket 22 sisältää lukuisia eri kisoja, kuten Ashes, Big Bash, The Hundred ja monia muita. Uudet pelimekaniikat ja selostukset sekä tarinavetoinen uratila vievät sinut saman tien sisään kaikkien aikojen kattavimpaan krikettikokemukseen. ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1821,33,'en-fr','Cricket 22 delivers the most robust, substantial game of cricket that fans have ever seen. Enjoy the full licensed Ashes contest – the pinnacle of the long-standing rivalry between Australia and England. In addition, contest Australia’s big-hitting Big Bash T20 competition, the hugely innovative The Hundred in England, the tropical party of the CPL in the Caribbean, and take to the international field of battle with fully-licensed teams from Australia, England, The West Indies, New Zealand and Ireland. ','Cricket 22 offre le jeu de cricket le plus solide et le plus complet que les fans aient jamais vu. Profitez de l\'intégralité de la compétition des Cendres sous licence - l\'apogée de la rivalité de longue date entre l\'Australie et l\'Angleterre. En outre, participez à la compétition Big Bash T20 en Australie, à la très innovante The Hundred en Angleterre, à la fête tropicale de la CPL dans les Caraïbes, et rendez-vous sur le champ de bataille international avec des équipes sous licence d\'Australie, d\'Angleterre, des Antilles, de Nouvelle-Zélande et d\'Irlande. ','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
(1822,34,'en-fr','And, in keeping with Big Ant’s commitment to equality and equal representation, both the Men’s and Women’s games have been replicated across all of Cricket 22.','De plus, conformément à l\'engagement de Big Ant en faveur de l\'égalité et de la représentation égale, autant les matchs des hommes que ceux des femmes ont été reproduits dans l\'ensemble de Cricket 22.','DONE','2026-04-16 16:35:00','2026-04-16 16:35:00'),
